mapper.select:
SELECT f.id, COALESCE(s.id, p.spot_id) AS spotId, f.name, f.image_url AS image, f.description, f.address, f.rating, f.hotness, f.avg_price AS avgPrice, f.cuisine_name AS cuisineName FROM foods f LEFT JOIN pois p ON p.id = f.poi_id LEFT JOIN spots s ON s.id = p.spot_id WHERE f.status = 1
AND ( f.address LIKE CONCAT('%', #{city}, '%') OR p.city LIKE CONCAT('%', #{city}, '%') OR p.province LIKE CONCAT('%', #{city}, '%') OR s.city LIKE CONCAT('%', #{city}, '%') OR s.province LIKE CONCAT('%', #{city}, '%') OR s.name LIKE CONCAT('%', #{city}, '%') )
AND ( p.spot_id IN
#{spotId}
OR s.id IN
#{spotId}
)
AND f.price_level <= 1
AND f.price_level <= 2
ORDER BY f.rating DESC, f.hotness DESC, f.id ASC LIMIT #{limit}
